/* 教材正文：控制台项目 / Spring Boot 项目 / SQL 基础（每章约 5200 字） */
(function () {
  'use strict';
  var T = window.JAVA_TEXTBOOK || (window.JAVA_TEXTBOOK = {});

  T['project-console'] = {
    meta: '本章约 5200 字 · 建议 40 分钟 · 配套流程图与 3 道习题',
    blocks: [
      { h: '11.1 为什么要做一个完整项目' },
      { p: '学完语法、集合、异常，很多人仍然写不出一个能用的程序：知道 for 怎么写，却不知道一个菜单循环怎么组织；知道 List 怎么用，却不知道数据怎么保存。项目课的目的，是把分散的知识点串成一条可运行的业务链。' },
      { p: '这一章不依赖数据库和框架，只用 Java SE 做一个控制台图书管理系统：新增、查询、借书、还书、删除、保存到文件。代码量不大，但分层、校验、异常、持久化都会涉及。' },
      { flow: ['需求拆解', '实体 Book', 'Service 业务', 'Main 菜单', '文件保存', '测试'] },
      { h: '11.2 需求澄清：把口头需求变成验收标准' },
      { p: '先把“要做什么”写清楚，再动手写类。需求越具体，后面的类设计越稳。' },
      { list: ['图书字段：id（唯一）、书名、作者、价格、是否借出。', '功能：新增图书、按 id 查询、列出全部、借书、还书、删除、退出。', '规则：id 不能重复；借出的书不能再次借；还书前必须已借出；价格不能为负。', '数据：启动时从文件加载，修改后写回文件，退出后数据不丢。', '输入：所有菜单选项和数字都要校验，不能一输错就崩。'] },
      { p: '真实场景里拿到的需求往往只有一句话：帮我做个图书管理。这句话里藏着大量空白：谁来用、数据从哪里来、一本书能不能被多人借、删除要不要二次确认、退出时是否必须保存。不先问清楚就动手，写出来的东西大概率返工。练习时可以把这些空白自己补上，并写成一段需求说明，模拟一次需求评审。' },
      { p: '补空白的方法是逐项追问。用户是谁：馆员还是读者。使用场景：单机还是多人同时用。数据规模：几十本还是几十万本。操作频率：一天几次还是每秒几次。失败容忍度：丢一条数据是否可以接受。每个问题的答案都会影响后面的设计，比如允许并发借阅就必须考虑锁，而单机练习可以直接忽略。' },
      { p: '把每条功能改写成可验证的句子：给定什么条件，执行什么操作，期望什么结果。例如，给定已存在 id 为 1 的图书，执行新增 id 为 1 的图书，期望提示 id 已存在且列表数量不变。这样写的好处是测试用例几乎可以直接从需求抄过来，不用等代码写完再临时想怎么测。' },
      { p: '需求要分优先级，按轮次交付。第一轮只做最小闭环：新增、列表、退出、内存存储，能跑通就说明菜单循环和分层是通的；第二轮加借书、还书、删除；第三轮加文件持久化；第四轮补边界校验和异常提示。每一轮结束都应该能运行、能演示，避免写了几天才发现方向错了。' },
      { p: '列一份不做清单同样重要：不做登录、不做多用户、不做并发借阅、不做图形界面、不接入网络。范围写清楚，才不会在实现借书时突然想加一套用户体系，把两天的小项目拖成两周。需求文档不是形式，它决定了你什么时候可以停下来。' },
      { p: '需求评审还有个实用技巧：把每条需求念给一个不懂编程的人听，看对方能不能复述出操作步骤。如果对方问出那本书被借走了列表里怎么显示，说明需求里缺了状态展示；如果对方问删错了能不能恢复，说明缺了确认与恢复策略。这些追问往往比技术评审更早发现问题。' },
      { h: '11.3 分层：实体、服务、入口' },
      { p: '把代码分成三层：Book 只保存数据；BookService 负责业务规则和集合操作；Main 只负责菜单、输入输出。分层的好处是每一层都能单独测试，修改界面不影响业务，修改存储也不影响界面。' },
      { table: { head: ['层', '职责', '不应该做什么'], rows: [
        ['Book', '字段、构造器、getter/setter', '业务判断、打印菜单'],
        ['BookService', '增删查改、借还规则、持久化', '读键盘、打印菜单'],
        ['Main', '菜单循环、输入校验、调用服务', '直接操作 List、写业务规则']
      ] } },
      { p: '把所有类写在一个文件里也能运行，但很快会乱。建议一开始就分包：model 放 Book，service 放 BookService，store 放 BookStore 接口与 FileBookStore 实现，ui 放 ConsoleUI 和输入工具，exception 放 BusinessException。目录结构与包名一致，类名与文件名一致，找代码时不用搜索。' },
      { p: '包之间要有明确的依赖方向：ui 依赖 service，service 依赖 store 接口和 model，store 的实现依赖 model，model 不依赖任何业务包。方向单一，改动就可控：换界面不用动 Service，换存储只要新增一个实现类。反过来，如果 Service 里写了打印语句或 import 了 ui，业务逻辑就和控制台绑死，测试时必须先造一个终端。' },
      { p: '判断依赖是否合理有个简单办法：问这一层能不能在没有下一层的情况下编译。model 和 exception 应该独立编译；Service 只依赖 store 的接口，因此可以注入内存实现；ui 依赖 Service，但 Service 不知道 ui 的存在。编译顺序清楚，循环依赖自然消失。' },
      { p: '包名不要用 test、util、common 这种大杂烩。输入校验放 ui，字符串处理放一个职责明确的小类，异常放 exception。名字越具体，半年后回来看越省力，接手的人也越容易判断一段代码该不该放在这里。' },
      { p: '构建工具也值得早点接触。用 Maven 或 Gradle 管理目录和依赖，源码放 src/main/java，测试放 src/test/java，编译、测试、打包都是一条命令。手写 javac 加 java 也能跑，但一旦引入第三方库，classpath 会迅速变成负担，而构建工具连版本冲突都能帮你提前发现。' },
      { h: '11.4 关键类设计与接口抽象' },
      { p: '实体类用私有字段 + 构造器 + getter/setter，借出状态用 boolean。id 创建后不应修改，所以用 final；其他字段按业务需要提供 setter。' },
      { code: 'public class Book {\n    private final int id;\n    private String title;\n    private String author;\n    private double price;\n    private boolean borrowed;\n\n    public Book(int id, String title, String author, double price) {\n        this.id = id;\n        this.title = title;\n        this.author = author;\n        this.price = price;\n    }\n\n    public int getId() { return id; }\n    public String getTitle() { return title; }\n    public String getAuthor() { return author; }\n    public double getPrice() { return price; }\n    public boolean isBorrowed() { return borrowed; }\n    public void setBorrowed(boolean borrowed) { this.borrowed = borrowed; }\n\n    @Override\n    public String toString() {\n        return id + " | " + title + " | " + author + " | " + price + " | " + (borrowed ? "已借出" : "在馆");\n    }\n}', title: 'Book.java' },
      { p: '五个类的职责要能一句话说清。Book 只描述数据，字段私有，提供构造器和访问器；BookService 持有图书集合并实现全部业务规则；BookStore 定义 save 和 load 两个方法；FileBookStore 用文件实现它；ConsoleUI 负责菜单循环和所有键盘交互；BusinessException 承载可以直接展示给用户的中文提示。' },
      { p: 'BookStore 用接口而不是直接在 Service 里写文件，是为了让 Service 可测试。测试时传入一个内存实现，数据放在 ArrayList 里，save 和 load 变成简单复制，测试不碰磁盘，也不会因为上次运行残留的文件导致结果时好时坏。这是面向接口编程最朴素的好处，不需要背概念也能体会。' },
      { p: 'Service 通过构造器接收 BookStore，而不是在字段里直接 new FileBookStore。构造器注入让依赖显式可见：看构造器就知道这个类需要什么，在 main 里也能决定用文件实现还是内存实现。字段直接 new 的写法把两者焊死，测试时只能改源码。' },
      { p: 'ConsoleUI 不要把 Scanner 传得到处都是。把读整数、读小数、读非空字符串封装成三个方法，统一处理重试和提示。菜单方法只负责读一个选项、调用一个 Service 方法、打印结果，每个分支不超过十行；超过十行通常说明业务判断漏到了界面层。' },
      { p: 'Book 要不要重写 equals 和 hashCode，是个值得想清楚的小问题。如果只按 id 判断相等，重写之后 contains、remove 的语义就统一了，不必先查再删；但把可变对象放进哈希集合当键，字段一变就再也找不到。练习阶段可以先不重写，删除时用查到的对象引用，等理解了哈希集合再补，并顺手重写 toString 方便打印调试。' },
      { h: '11.5 输入层：为什么统一用 nextLine' },
      { p: '初学者最常遇到的怪现象是：输入完数字按回车，下一个请输入书名的提示还没等你输入就跳过了。原因是 nextInt 只从缓冲区取走数字，回车符还留着，紧接着的 nextLine 读到这个空行立刻返回空字符串。这不是 bug，是 Scanner 按分隔符读取的必然结果。' },
      { p: '解决办法不是到处补一个 nextLine，而是从源头统一：所有输入都用 nextLine 读整行，需要数字时再用 Integer.parseInt 或 Double.parseDouble 转换。缓冲区永远被整行消费，不会残留换行符；格式错误由转换抛出 NumberFormatException，在方法内部捕获并重试，调用方拿到的永远是合法值。' },
      { p: '读非空字符串也要循环：trim 之后长度为 0 就提示重输。书名允许中文、空格和标点，但不允许空；价格允许小数，但要拒绝负数和明显不合理的值。把这些规则集中在输入方法里，Service 就不必重复判断是不是空串。' },
      { p: '还有一个细节：不要用 hasNextInt 判断后再调 nextInt。非法输入会一直留在缓冲区，下一次判断仍然为假，循环变成死循环，屏幕疯狂刷提示。用 nextLine 加解析的方式，非法内容已经被取走，重试才有可能成功。这个区别在排查卡死问题时非常关键。' },
      { p: '读小数的实现与读整数同构：循环读整行，parseDouble 失败就提示重输，成功后检查是否大于等于零。展示时不要直接拼接 double，用 String.format 保留两位小数，否则会出现 59.0 和 59.000000001 这类显示差异。输入提示里写清期望格式，例如请输入价格，最多两位小数，能减少一半无效输入。' },
      { p: 'Main 用一个 while 循环打印菜单，读取选项，用 switch 分发。所有 nextInt 都用 try-catch 或 hasNextInt 校验；非法输入清掉缓冲区，提示后重新循环。' },
      { code: 'public class Main {\n    private static final Scanner SC = new Scanner(System.in);\n    private static final BookService SERVICE = new BookService();\n\n    public static void main(String[] args) {\n        while (true) {\n            System.out.println("1.新增 2.查询 3.列表 4.借书 5.还书 6.删除 0.退出");\n            System.out.print("请选择：");\n            String line = SC.nextLine().trim();\n            try {\n                switch (line) {\n                    case "1" -> addBook();\n                    case "2" -> queryBook();\n                    case "3" -> listBooks();\n                    case "4" -> borrowBook();\n                    case "5" -> returnBook();\n                    case "6" -> removeBook();\n                    case "0" -> { System.out.println("再见"); return; }\n                    default -> System.out.println("无效选项");\n                }\n            } catch (RuntimeException e) {\n                System.out.println("操作失败：" + e.getMessage());\n            }\n        }\n    }\n\n    static void addBook() {\n        int id = readInt("id：");\n        System.out.print("书名：");\n        String title = SC.nextLine();\n        System.out.print("作者：");\n        String author = SC.nextLine();\n        double price = readDouble("价格：");\n        SERVICE.add(new Book(id, title, author, price));\n        System.out.println("新增成功");\n    }\n\n    static int readInt(String prompt) {\n        while (true) {\n            System.out.print(prompt);\n            String s = SC.nextLine().trim();\n            try { return Integer.parseInt(s); }\n            catch (NumberFormatException e) { System.out.println("请输入整数"); }\n        }\n    }\n}', title: 'Main.java' },
      { h: '11.6 业务层：校验顺序与异常语义' },
      { p: 'Service 持有 <code>List&lt;Book&gt;</code>，提供 add、findById、listAll、borrow、returnBook、remove。每个方法先校验，再修改状态。查询用 Stream 的 filter + findFirst，找不到抛业务异常。' },
      { code: 'public class BookService {\n    private final List<Book> books = new ArrayList<>();\n\n    public void add(Book book) {\n        if (findByIdOrNull(book.getId()) != null) {\n            throw new IllegalArgumentException("id 已存在: " + book.getId());\n        }\n        books.add(book);\n    }\n\n    public Book findById(int id) {\n        Book book = findByIdOrNull(id);\n        if (book == null) throw new IllegalArgumentException("图书不存在: " + id);\n        return book;\n    }\n\n    private Book findByIdOrNull(int id) {\n        return books.stream().filter(b -> b.getId() == id).findFirst().orElse(null);\n    }\n\n    public List<Book> listAll() { return List.copyOf(books); }\n\n    public void borrow(int id) {\n        Book book = findById(id);\n        if (book.isBorrowed()) throw new IllegalStateException("该书已借出");\n        book.setBorrowed(true);\n    }\n\n    public void returnBook(int id) {\n        Book book = findById(id);\n        if (!book.isBorrowed()) throw new IllegalStateException("该书未借出");\n        book.setBorrowed(false);\n    }\n\n    public void remove(int id) {\n        Book book = findById(id);\n        books.remove(book);\n    }\n}', title: 'BookService.java' },
      { p: '注意 listAll 返回 <code>List.copyOf(books)</code> 而不是内部列表：外部拿到只读副本，无法绕过 Service 直接增删。这是封装在集合上的应用。' },
      { p: '校验要分三层，各管各的。界面层管格式：是不是数字、是不是空串；业务层管规则：id 是否重复、书是否已借出、价格是否为负；存储层管完整性：文件字段够不够、数字能不能解析。三层都做自己该做的，不要越界，也不要把所有判断堆在 main 里。' },
      { p: '同一个方法里的判断顺序也有讲究：先判空，再判范围，再判唯一性，最后判状态。以借书为例，先确认 id 对应的书存在，再确认它当前是在馆状态，最后才修改借出字段。顺序反了会出现书不存在却提示已借出这种误导性错误，用户按提示操作只会更困惑。' },
      { p: '异常类型要能表达语义。参数本身不合法用 IllegalArgumentException，例如价格为负、id 重复；对象当前状态不允许该操作用 IllegalStateException，例如对已借出的书再次借阅；需要直接展示给用户的中文提示用自定义 BusinessException，界面层只捕获它并打印 message，其他异常说明是程序缺陷，应该保留堆栈方便排查。' },
      { p: '不要在 Service 里打印。Service 打印意味着它绑定了控制台，将来换成 Web 接口时这些输出全部作废。让 Service 只抛异常或返回结果，由界面层决定怎么展示，这是分层最容易被破坏、又最值得坚持的一条。' },
      { p: 'Service 的方法该返回什么也要提前定好。查不到时返回 null 还是抛异常，两种风格不能混用：混用会让调用方既判空又 catch，代码迅速变脏。建议查询单个对象的方法抛业务异常，返回集合的方法给空集合而不是 null，这样调用方永远不需要判空，也不会因为漏判而出现空指针。' },
      { p: '还有一个容易忽略的设计问题：id 由谁生成。让用户手输 id 最简单，但用户会输重复、负数、超大数，Service 必须逐项校验；改成系统自增，由 Service 维护下一个可用编号，新增时不再让用户输入，重复问题从源头消失，代价是加载文件后要把计数器恢复为最大值加一。生产项目几乎都选后者，因为让用户承担唯一性责任本身就是设计缺陷。' },
      { p: '业务异常用 IllegalArgumentException/IllegalStateException 表达，Main 统一 catch 后打印 message，不打印堆栈给用户。输入解析失败在 readInt 内重试，不把异常抛到菜单层。' },
      { h: '11.7 存储层：原子写入与容错加载' },
      { p: '把每本书写成一行“id|书名|作者|价格|是否借出”，用 <code>Files.write</code> 保存、<code>Files.readAllLines</code> 加载。字段分隔符要避免出现在书名里；简单项目用竖线，生产项目用 JSON/CSV 库。' },
      { code: 'public void save(Path path) throws IOException {\n    List<String> lines = new ArrayList<>();\n    for (Book b : books) {\n        lines.add(b.getId() + "|" + b.getTitle() + "|" + b.getAuthor() + "|" + b.getPrice() + "|" + b.isBorrowed());\n    }\n    Files.write(path, lines, StandardCharsets.UTF_8);\n}\n\npublic void load(Path path) throws IOException {\n    if (!Files.exists(path)) return;\n    for (String line : Files.readAllLines(path, StandardCharsets.UTF_8)) {\n        String[] p = line.split("\\\\|");\n        Book b = new Book(Integer.parseInt(p[0]), p[1], p[2], Double.parseDouble(p[3]));\n        b.setBorrowed(Boolean.parseBoolean(p[4]));\n        books.add(b);\n    }\n}', title: 'Persistence.java' },
      { p: '加载时要处理空行、字段数量不对、数字格式错误；保存时用临时文件 + 原子移动，避免写到一半崩溃导致数据损坏。简单项目可以先直接覆盖，但要意识到风险。' },
      { p: '直接往目标文件里覆盖写，如果写到一半断电或抛异常，文件会变成半截内容，下次启动全部解析失败。稳妥做法是先写同目录下的临时文件，写完后用 Files.move 加 ATOMIC_MOVE 覆盖目标文件。同一文件系统内的移动是原子操作，要么旧文件完整，要么新文件完整，不会出现中间态。' },
      { p: '加载要假设文件是脏的。逐行读取时跳过空行；split 之后先检查数组长度是否等于五；对 id 和价格做 try-catch 解析，失败的行跳过并记录行号；借出字段只接受 true 或 false，其他值按 false 处理。宁可丢一行坏数据，也不要让整个程序启动失败，用户至少还能看到其余数据。' },
      { p: '分隔符的选择要考虑内容。竖线在书名里不常见，但不是不可能，所以保存前要把字段里的竖线替换成全角字符，或者改用制表符并禁止输入制表符。更正规的做法是用 JSON 库序列化，让库去处理转义；手写拼接只适合练习，不适合有真实用户的数据。' },
      { p: '保存时机也要想清楚：每次增删改后立即保存最安全，但写盘频繁；退出时统一保存最快，但程序崩溃会丢数据。控制台项目数据量小，建议每次修改后保存，并在保存失败时明确提示用户，而不是静默吞掉异常。' },
      { p: '文件路径同样容易出问题。写 data/books.txt 这种相对路径时，基准目录是进程的工作目录，在 IDE 里运行和在终端里运行未必相同，于是同一份代码在别人电脑上就读不到数据。练习阶段可以打印 toAbsolutePath 确认实际位置，或者把数据文件放到用户目录下的固定路径，并在启动时创建父目录。' },
      { h: '11.8 故障排查：八个典型症状与常见坑' },
      { p: '症状一：启动就报 NumberFormatException。原因通常是加载时把表头或空行也当数据解析。修法是跳过首行和空行，解析前判断字段数量，并对每个数字字段单独 try-catch，报错时打印行号。' },
      { p: '症状二：新增成功但列表里看不到。检查是否把书加到了另一个集合实例，或者在 listAll 里返回了新建的空列表。打印集合长度是最快的定位手段，比反复读代码有效。' },
      { p: '症状三：删除时报 ConcurrentModificationException。这是用 for-each 遍历时直接调用 remove 造成的。改用 Iterator 的 remove，或者先收集要删的元素再统一删除，或者用 removeIf 一行解决。' },
      { p: '症状四：借书后重启又变回在馆。说明借出字段没有写进文件，或者加载时没有读回来。对照保存行的字段顺序和加载时的下标，一位错位就会导致后面全部错位，价格被读成借出状态这种荒唐结果就是这样来的。' },
      { p: '症状五：输入字母后程序疯狂刷屏。这是 nextInt 抛异常后没有消费非法输入，循环立刻再次读取同一段内容。改成 nextLine 加解析即可，不要试图用异常跳出来。' },
      { p: '症状六：中文写入文件后打开是乱码。读写都要显式指定 StandardCharsets.UTF_8，不要依赖平台默认编码，Windows 默认编码与 macOS 不同，换机器就会暴露问题。' },
      { p: '症状七：价格显示成 59.0 或 59.00 不统一。double 只适合练习，真实金额用 BigDecimal，并在展示时用 String.format 固定小数位，避免同一个价格在不同页面显示不同。' },
      { p: '症状八：程序能跑但结果不对，且没有任何报错。这类问题最花时间，解决方式是加日志：在 Service 方法入口打印参数，出口打印结果，用日志还原一次完整操作序列，异常往往一眼可见。' },
      { list: ['把 Scanner 和业务逻辑全写在 main 里，后期无法维护。', '遍历 List 时直接 remove，抛 ConcurrentModificationException。', '文件写入没有 close/flush，重启后数据丢失。', 'id 重复、价格负数没有校验，数据一开始就是脏的。', '把内部 List 直接返回，外部可以绕过 Service 修改。'] },
      { h: '11.9 调试与验收方法' },
      { p: '调试从缩小范围开始。怀疑业务规则，就写一个临时 main 直接 new Service 并调用方法，不经过菜单；怀疑输入，就只在读取方法里打印原始字符串。把问题隔离在一层之内，比在完整流程里猜要快得多。' },
      { p: '断点要会用条件。借书失败只在某个 id 时复现，就给断点加条件，只在 id 等于目标值时停下，避免每次循环都中断。观察变量时重点看集合长度、对象的借出字段和异常的 message，这三处能解释大部分错误。' },
      { p: '验收要按清单走，不凭感觉。准备一份包含正常流程和边界情况的用例：新增重复 id、查询不存在的 id、借已借出的书、还从未借出的书、删除后再次查询、价格为零和负数、书名为空、输入非数字、文件被手动改坏。每条用例记录实际结果，与期望不符就记为缺陷。' },
      { p: '最后做一次重新开始测试：删掉数据文件，从零启动，走完新增到退出的全流程，再重启确认数据还在。这一步能暴露初始化顺序、文件路径和编码问题，也是交付前最值得做的一次检查。自动化程度高的项目可以把这些步骤写成脚本，减少手工遗漏。' },
      { p: '日志不必引入框架。写一个私有的 log 方法，统一输出时间、级别和上下文，就足够定位问题；关键是格式一致，并且带上能复现问题的信息，例如借书失败要打印图书 id 和当前状态。排查完把临时日志删掉或降级，避免正式运行时刷屏。' },
      { p: '如果条件允许，找一个人按你的说明操作，你只观察不提示。对方卡住的地方，就是说明缺失或提示不清的地方，这比自测更容易发现可用性问题。记录对方每一步的输入和预期，往往能补出三到五条遗漏的校验，也能检验提示语是否写得像人话。' },
      { p: '按下面的顺序手动测试，全部通过才算完成：新增两本书 → 列表 → 按 id 查询 → 借出一本 → 再次借出应失败 → 还书 → 删除 → 退出重开数据仍在 → 输入字母不应崩溃。' },
      { h: '11.10 从能用到好用：扩展路线' },
      { p: '第一层扩展是查询能力：按作者、按价格区间、按借出状态过滤，再加关键字模糊匹配和分页。实现时把过滤条件抽成一个参数对象，而不是给每种组合写一个方法，否则条件一多方法数量会爆炸。' },
      { p: '第二层是借阅记录：新增 BorrowRecord，记录书 id、借书人、借出时间和归还时间。书的状态可以由记录推导，避免两处数据不一致。这一步会自然引出什么时候该用关联对象、什么时候该冗余字段的设计问题。' },
      { p: '第三层是持久化升级：把内存集合换成数据库，把同步方法换成事务，把文件锁换成行锁。做完这一层，控制台项目就与后面的 Spring 章节接上了，Service 里的业务规则几乎可以原样搬过去。' },
      { p: '第四层是质量：给 Service 补单元测试，覆盖正常、边界和异常三类路径；把输入输出抽成接口，用假实现替代控制台；用构建工具统一跑测试和打包。能自动验证的项目，才敢继续改，否则每次加功能都像在拆炸弹。' },
      { h: '本章小结' },
      { list: ['分层：实体存数据、Service 管规则、Main 管交互。', '集合操作注意封装，返回只读副本。', '文件持久化要处理格式错误和写入失败。', '先跑通主流程，再补校验、异常和测试。'] },
      { h: '常见追问' },
      { list: [
        '<b>问：为什么一定要先拆需求再动手写？</b><br>答：需求拆解把「能跑」变成「能验收」：每条验收标准后面都要能对应到一个方法或一次手工操作，写代码时才知道什么时候算完成。不拆直接写，通常写到借书和删除互相牵连的时候才发现集合结构不合适，只能回头改。拆完还能顺手得到测试用例：给定什么条件、执行什么操作、期望什么结果，这三句话几乎可以原样抄进 JUnit。返工时也有依据，一对照就知道是需求漏了还是实现错了。',
        '<b>问：这么小的项目值得提取接口吗？</b><br>答：值得，但只提一层。项目小的时候，抽象的价值不在「将来可能换实现」，而在「现在能被测试」：BookService 只依赖 BookStore 接口，测试时传一个把数据放在 ArrayList 里的内存实现，save 和 load 变成简单复制，测试不碰磁盘，也不会因为上次运行残留的文件导致结果时好时坏。只提一层的意思是不再给 BookStore 套工厂、再给工厂套配置，两三层间接会把几百行的项目读成迷宫，收益抵不上成本。',
        '<b>问：为什么输入层要统一用 nextLine？</b><br>答：nextInt 只吃掉数字，回车符留在缓冲区，紧接着的 nextLine 会立刻读到空串，现象是「刚输入完菜单项就提示书名不能为空」。统一用 nextLine 读整行，再用 Integer.parseInt 自己转，换行处理就收敛到一处；解析失败抛 NumberFormatException，捕获后打印提示并重试。菜单循环里尤其明显，一次读错位，后面所有交互跟着错位，排查时还以为是业务逻辑的问题。'
      ] },
      { h: '自测与练习' },
      { p: '先自己动手做一遍，再展开参考答案对照预期现象与判断依据。' },
      { ol: [
        '增加「按作者查询」和「按价格排序」两个功能。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：菜单多出按作者查询、按价格排序两项；输入某个作者能打印该作者的全部图书，没有则提示未找到，列表原顺序不变。<b>为什么</b>：Book 里已经有 author 和 price 字段，缺的只是 Service 上的两个方法和 UI 上的两个分支，不用动实体和存储层。<b>要点</b>：写成 <code>List&lt;Book&gt; findByAuthor(String author)</code>，过滤时用 <code>author.equals(b.getAuthor())</code>；排序前先拷贝一份 <code>new ArrayList&lt;&gt;(books)</code>，再 <code>list.sort(Comparator.comparingDouble(Book::getPrice))</code>，否则会把存储顺序改掉。</div></details>',
        '把存储格式换成 JSON（可以手写拼接），并处理书名含分隔符的情况。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：保存后的文件能被同一个类的 load 读回来，行数与保存前一致；书名里带逗号、双引号、反斜杠的记录，字段也不会错位。<b>为什么</b>：手写拼接时用户数据直接进字符串，引号和反斜杠会破坏结构，解析时就多切一段或少切一段，这类错误只有边界数据才暴露。<b>要点</b>：字符串值必须转义反斜杠和双引号，且先转义反斜杠，顺序反了会二次转义；每条记录一行，load 时逐行 try/catch，坏行跳过并打印行号，不要让一行坏数据废掉整份文件。</div></details>',
        '给 Service 写 5 个 JUnit 测试，覆盖新增、重复 id、借书、重复借、还书。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：五个测试全部通过；重复 id 新增时抛 BusinessException 且集合大小不变；对已借出的书再借一次抛异常，状态仍是已借出。<b>为什么</b>：业务规则只有被断言过才算实现过，重复 id 和重复借这两条最容易在 UI 分支里漏掉，因为正常操作路径根本走不到。<b>要点</b>：<code>new BookService(new MemoryBookStore())</code> 注入内存实现，测试不碰磁盘；用 <code>assertThrows(BusinessException.class, ...)</code> 断言异常；数量断言写 <code>assertEquals(1, service.list().size())</code>，每个测试方法里重建 service 保证互不干扰。</div></details>',
        '把 Main 的菜单抽成独立类，Service 不依赖 Scanner。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：只有 ConsoleUI 里出现 Scanner；BookService 的 import 里查不到 java.util.Scanner，删掉菜单后 Service 仍能被测试直接调用。<b>为什么</b>：依赖方向单一才好测也才好换界面，Service 里读键盘等于把控制台和业务焊死，测试时必须先造一个终端输入。<b>要点</b>：ConsoleUI 持有一个 BookService 字段，菜单方法返回 boolean 控制循环；读整数、读非空串各自封装成私有方法统一重试，UI 方法里只做「读一个选项、调一次 Service、打印结果」。</div></details>'
      ] }
    ]
  };

  T['project-spring'] = {
    meta: '本章约 5200 字 · 建议 40 分钟 · 配套流程图与 3 道习题',
    blocks: [
      { h: '12.1 从控制台到 Web 接口：HTTP 与 REST' },
      { p: '控制台项目只能自己用，Web 接口可以让浏览器、App、其他服务调用。Spring Boot 把“启动、配置、路由、JSON 转换”都封装好，你只需要写 Controller、Service、Repository。' },
      { flow: ['start.spring.io', 'Controller', 'Service', 'Repository', '数据库', 'HTTP 响应'] },
            { p: '浏览器访问一个地址，本质是发一个 HTTP 请求：方法、路径、请求头、可选的请求体。服务器回一个响应：状态码、响应头、响应体。REST 是把资源放在路径里，用方法表达动作：GET 查、POST 建、PUT 改、DELETE 删。路径用名词复数，不要写 getBookById 这种把动词塞进 URL 的写法。' },
      { p: '状态码不是随便填的。200 表示成功读取，201 表示创建成功并通常带 Location 头，204 表示成功但没有响应体，400 表示请求参数有问题，401 表示未认证，403 表示已认证但无权限，404 表示资源不存在，409 表示与当前状态冲突，500 表示服务端未预料到的错误。前端和监控都依赖这些语义，全部返回 200 会让排查失去线索。' },
      { p: '请求体和查询参数要分清。查询参数适合过滤、分页、排序，出现在 URL 上，会被访问日志记录；请求体适合提交完整对象，支持嵌套结构和较长文本。把密码或长文本放 URL 上会进日志和浏览器历史，属于常见事故。' },
      { p: '一个接口设计得好不好，看它能不能被没读过文档的人猜出来。/api/books 表示图书集合，/api/books/42 表示某一本，/api/books/42/borrow 表示对这本书执行借阅这个子资源动作。命名一致，前端联调成本会明显下降。' },
      { p: '还要约定幂等性。GET、PUT、DELETE 应当幂等，重复调用结果一致；POST 通常不幂等，重复提交会创建多条数据。支付、下单这类接口要额外做幂等键，否则网络重试就会产生重复订单。这个约定在单体应用阶段就该建立，等到拆服务时已经来不及补。' },
      { h: '12.2 用 start.spring.io 建项目：骨架与配置' },
      { p: '选择 Maven、Java 17+、Spring Web，下载解压后用 IDE 打开。目录结构是 src/main/java 放代码，src/main/resources 放配置，src/test/java 放测试。' },
      { code: 'demo/\n├── pom.xml\n├── src/main/java/com/example/demo/\n│   ├── DemoApplication.java\n│   ├── controller/BookController.java\n│   ├── service/BookService.java\n│   └── model/Book.java\n└── src/main/resources/application.yml', title: '项目结构' },
      { p: 'pom.xml 里的 spring-boot-starter-web 带来 Spring MVC、内嵌 Tomcat、Jackson。启动类上的 @SpringBootApplication 开启自动配置和组件扫描。' },
      { p: 'start.spring.io 生成的项目里，pom.xml 决定依赖和 Java 版本。spring-boot-starter-parent 统一管理版本号，所以引入 starter 时通常不写版本；spring-boot-starter-web 带来 MVC、Jackson 和内嵌 Tomcat；加上 spring-boot-starter-data-jpa 才会有 JPA 和 Hibernate。' },
      { p: '启动类上的 @SpringBootApplication 是三个注解的组合：配置类、自动配置、组件扫描。组件扫描从启动类所在包往下找，所以 Controller 必须放在启动类的子包里。放到同级或上级包会扫不到，表现为接口 404 但代码没有任何报错，这是新手最常见的困惑之一。' },
      { p: 'application.yml 里至少配置端口、数据源和 JPA 行为。开发环境用 H2 内存库最省事，ddl-auto 设为 update 或 create-drop；生产环境必须改成 validate 或 none，让表结构由迁移脚本管理，避免应用启动时悄悄改表。一个字段类型被自动改掉，可能直接导致线上查询变慢。' },
      { p: '配置不要写死在代码里。数据库地址、密码、超时时间通过配置文件或环境变量注入，用 @ConfigurationProperties 绑定成对象，比到处写 @Value 更清晰，也有类型校验。敏感信息不进 Git，本地用环境变量或未提交的配置文件，这一点从第一个项目就要养成习惯。' },
      { p: '依赖引入要克制。每加一个 starter 都会带来一批自动配置和启动开销，也扩大升级时的兼容面。用不到的功能不要因为教程里出现过就加进来，pom 文件应该能解释每个依赖为什么存在。' },
      { p: '启动失败先看日志最上面几行，而不是最下面。端口被占用会明确写 Port 8080 was already in use，改配置或结束占用进程即可；数据源连不上会写 Communications link failure，先确认数据库是否启动、地址和账号是否正确，不要急着重装环境。' },
      { h: '12.3 分层落地：DTO、Entity、Service、Controller 的边界' },
      { p: 'Book 用普通 JavaBean 或 record；Controller 只做参数接收和响应；Service 写业务规则；Repository 访问数据库。不要在 Controller 里写 SQL，也不要在 Repository 里做业务判断。' },
      { code: '@Entity\npublic class Book {\n    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n    private String title;\n    private String author;\n    private double price;\n    // 无参构造器、getter/setter 省略\n}\n\npublic interface BookRepository extends JpaRepository<Book, Long> {\n    List<Book> findByTitleContaining(String keyword);\n}', title: 'Book.java' },
      { p: '实体类直接当接口入参和出参，小项目能跑，但有三个隐患：暴露数据库字段、无法表达创建时不需要 id 这种差异、校验注解会同时约束数据库和接口。更稳的做法是加 DTO：CreateBookRequest 只含客户端该传的字段，BookResponse 只含该返回的字段。' },
      { p: '转换代码集中写在一处，例如在 Service 里把请求对象转成实体，或者用实体的静态工厂方法 from。不要在 Controller 里散落十几行 set 调用，也不要让 DTO 反过来依赖实体层的内部结构。' },
      { p: 'Controller 的职责只有四件事：接收参数、调用 Service、包装响应、决定状态码。它不应该判断价格是否为负，也不应该捕获所有异常后返回一段字符串。Controller 越薄，换协议时复用越多，比如后来加一个命令行入口或消息队列消费者。' },
      { p: 'Service 的职责是业务规则和事务边界。它接收普通 Java 对象，不感知 HTTP；它抛出的异常由统一异常处理翻译成状态码。Repository 只做数据访问，简单查询用方法名派生，复杂查询才写 @Query，并且把 SQL 放在数据访问层，不要泄漏到 Service。' },
      { p: '包结构按功能分还是按层分，小项目差别不大，但要有统一规则。按层分是 controller、service、repository、model 四个包；按功能分是 book、author、order 各自包含自己的四层。功能变多之后，按功能分更容易定位和拆分，代价是初期要多建几个包。' },
      { p: '接口的入参出参一旦定下就是契约，改动要考虑调用方。新增字段通常兼容，删除或改类型是破坏性变更。给接口加版本号或者保留旧字段一段时间，比直接改掉更稳妥，尤其是当调用方是别人的客户端时。' },
      { p: '列表接口要提前定分页结构，返回 items、total、page、size 四个字段，而不是直接返回一个数组。直接返回数组时，前端拿不到总数，后面想加分页就得改契约；提前定好，前端写列表页时不用等后端再改一次。' },
      { h: '12.4 Service：业务与事务边界' },
      { p: 'Service 负责校验、业务规则和事务边界。方法上加 @Transactional，抛 RuntimeException 时自动回滚；查询方法可以加 @Transactional(readOnly = true)。' },
      { code: '@Service\npublic class BookService {\n    private final BookRepository repository;\n\n    public BookService(BookRepository repository) {\n        this.repository = repository;\n    }\n\n    public List<Book> findAll() {\n        return repository.findAll();\n    }\n\n    public Book findById(Long id) {\n        return repository.findById(id)\n                .orElseThrow(() -> new IllegalArgumentException("图书不存在: " + id));\n    }\n\n    @Transactional\n    public Book create(Book book) {\n        if (book.getPrice() < 0) throw new IllegalArgumentException("价格不能为负");\n        return repository.save(book);\n    }\n}', title: 'BookService.java' },
      { p: '@Transactional 的本质是方法执行前开启事务，正常返回提交，抛 RuntimeException 或 Error 时回滚。受检异常默认不回滚，需要显式写 rollbackFor = Exception.class。这一点在调用文件或网络客户端时特别容易踩，表面上抛了异常，数据库却已经提交。' },
      { p: '同类内部调用会让事务失效。A 方法调用本类的 B 方法，B 上的 @Transactional 不会生效，因为调用没有经过代理对象。解决办法是把 B 移到另一个 Bean，或者注入自身代理，或者把事务边界上移到 A。理解代理这件事，比背注解参数有用得多。' },
      { p: '事务方法不要做耗时操作。在事务里调用远程接口、发消息、生成大文件，会长时间占用数据库连接，连接池很快被耗尽。正确做法是先完成事务内的数据修改，提交后再异步执行副作用，失败时用补偿或重试处理。' },
      { p: '只读查询加 @Transactional(readOnly = true) 能让驱动做优化，也能在代码层面表明意图。批量操作要注意事务大小，一次提交十万行会撑爆日志和内存，应该分批提交并记录进度。' },
      { p: '事务的传播行为决定了方法之间如何共享事务。默认的 REQUIRED 表示有事务就加入、没有就新建，适合大多数场景；REQUIRES_NEW 会挂起当前事务另开一个，适合记录日志这类即使主流程回滚也要保留的操作。用错传播行为，回滚范围就和预期不一致。' },
      { p: '事务和缓存的顺序也要一致：先提交事务，再删除缓存，否则并发读会把旧值重新写回缓存。删除失败要重试或记录，不能假设缓存一定删成功。缓存不是数据库的附属品，它的一致性需要在设计时就想清楚。' },
      { h: '12.5 Controller：REST 接口与 JSON 参数绑定' },
      { p: '用 @RestController + @RequestMapping 定义资源路径，GET 查询、POST 新增、PUT 修改、DELETE 删除。路径变量用 @PathVariable，查询参数用 @RequestParam，请求体用 @RequestBody。' },
      { code: '@RestController\n@RequestMapping("/api/books")\npublic class BookController {\n    private final BookService service;\n\n    public BookController(BookService service) { this.service = service; }\n\n    @GetMapping\n    public List<Book> list(@RequestParam(required = false) String keyword) {\n        return service.findAll();\n    }\n\n    @GetMapping("/{id}")\n    public Book get(@PathVariable Long id) {\n        return service.findById(id);\n    }\n\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    public Book create(@RequestBody Book book) {\n        return service.create(book);\n    }\n\n    @DeleteMapping("/{id}")\n    @ResponseStatus(HttpStatus.NO_CONTENT)\n    public void delete(@PathVariable Long id) {\n        service.delete(id);\n    }\n}', title: 'BookController.java' },
      { p: 'Spring Boot 默认用 Jackson 把对象转 JSON。请求体 JSON 的字段名要与实体属性一致，或用 @JsonProperty 映射。日期、枚举、泛型集合需要额外配置。' },
      { table: { head: ['注解', '接收位置', '示例'], rows: [
        ['@PathVariable', 'URL 路径', '/api/books/1 中的 1'],
        ['@RequestParam', '查询参数', '?keyword=java'],
        ['@RequestBody', '请求体 JSON', 'POST 的整个对象'],
        ['@RequestHeader', '请求头', 'Authorization']
      ] } },
      { h: '12.6 参数校验：Bean Validation' },
      { p: '在 DTO 字段上加 @NotBlank、@NotNull、@Min、@Size、@Email，在 Controller 参数上加 @Valid，校验失败会抛 MethodArgumentNotValidException，默认返回 400。这比在 Service 里手写一堆 if 更集中，也不容易漏掉某个入口。' },
      { p: '默认错误信息是英文且不够具体，可以在注解里写 message，再用统一异常处理把字段名和提示拼成结构化 JSON。前端拿到 field 和 message 就能直接定位到输入框，不用猜是哪一项错了。' },
      { p: '分组校验解决新增和修改规则不同的问题：新增时 id 必须为空，修改时 id 必须存在。定义两个标记接口，在 @Validated 里指定分组，比写两套 DTO 更轻，也更不容易出现两套规则不同步。' },
      { p: '校验只保证格式，不保证业务。价格不能为负可以靠 @Min，但同一作者同一书名不能重复必须查库，属于 Service 的职责。不要把业务规则硬塞进注解，也不要因为有了注解就删掉 Service 的防御性检查，因为 Service 可能被其他入口调用。' },
      { p: '嵌套对象要加 @Valid 才会级联校验，集合元素要加 @Valid 配合泛型。漏了这两个注解，内层字段即使写了约束也不会生效，而且不会报错，只能靠测试发现。' },
      { p: '还有一个隐蔽的坑：在 int 这种基本类型上写 @NotNull 永远通过，因为基本类型不可能为 null，没传时默认是 0。要区分未传和传 0，必须改用 Integer；布尔字段同理，用 Boolean 才能表达未填。类型选错，校验注解就形同虚设。' },
      { h: '12.7 统一响应与异常处理' },
      { p: '用 @RestControllerAdvice + @ExceptionHandler 把异常转成统一 JSON：状态码、错误码、message。不要让前端收到 500 HTML 堆栈。' },
      { code: '@RestControllerAdvice\npublic class GlobalExceptionHandler {\n    @ExceptionHandler(IllegalArgumentException.class)\n    @ResponseStatus(HttpStatus.BAD_REQUEST)\n    public Map<String, String> badRequest(IllegalArgumentException e) {\n        return Map.of("error", e.getMessage());\n    }\n}', title: 'GlobalExceptionHandler.java' },
      { p: '统一响应的价值是让前端只写一套解析逻辑。常见结构是 code、message、data 三个字段，成功时 code 为 0，业务失败用非 0 码，HTTP 状态码仍然保持语义正确。不要把所有错误都塞进 200 响应体，那会让网关、监控和重试策略全部失效。' },
      { p: '@RestControllerAdvice 集中处理异常，按异常类型分方法：参数校验失败返回 400 和字段列表，资源不存在返回 404，状态冲突返回 409，未预料异常返回 500 并记录日志。日志里要有请求路径、参数摘要和堆栈，响应里不要有堆栈。' },
      { p: '自定义业务异常继承 RuntimeException，携带错误码。Service 抛它，异常处理器翻译成对应状态码和提示。这样 Service 不需要知道 HTTP，新增接口时也能复用同一套错误语义。' },
      { p: '不要捕获异常后什么都不做。空的 catch 块会让问题消失在下游，排查时只能看到数据不对。至少记录日志，或者包装成业务异常继续抛并保留原始 cause，否则堆栈断在这里，根本不知道根因在哪。' },
      { p: '响应里不要回显数据库字段名、SQL 语句和内部类名。这些信息对攻击者有价值，对用户没有意义。错误提示写给用户看，日志写给开发看，两者要分开。' },
      { p: '错误码要稳定。同一个业务错误在所有接口里用同一个码，前端才能统一处理；不要把异常类名直接当错误码，重构一次就全变了。错误码表放在文档里维护，新增时先查表再定义，避免同一个含义出现三个码。' },
      { h: '12.8 一次创建请求的完整链路' },
      { p: '以 POST /api/books 为例，从请求进来到响应返回会经过一串固定环节。理解这条链路，出错时才知道该在哪一环停下来看，而不是把所有问题都归咎于数据库。' },
      { p: '请求先经过内嵌 Tomcat 的线程池，再进入 Spring 的过滤器链，编码、跨域、安全认证都在这里处理。接着 DispatcherServlet 根据路径找到 Controller 方法，把 JSON 请求体反序列化成 DTO，同时执行 Bean Validation 校验。' },
      { p: '校验通过后进入 Controller，Controller 调用 Service。Service 方法上如果有 @Transactional，此时事务开启；Repository 的 save 最终转成一条 INSERT，由连接池里的连接执行。方法正常返回后事务提交，异常则回滚。' },
      { p: '返回值沿原路返回：实体或 DTO 被 Jackson 序列化成 JSON，状态码由 @ResponseStatus 或 ResponseEntity 决定，创建成功时响应头可能带 Location。任何一层抛出异常，都会跳到异常处理器，被翻译成统一结构。' },
      { p: '排查时按这个顺序定位：先用日志确认请求是否到达过滤器，再看 DispatcherServlet 有没有匹配到 handler，再看参数绑定和校验结果，最后看 SQL 是否执行、事务是否提交。每一步都有对应的日志或断点，逐段排除比整体猜测有效。' },
      { p: '常见的时间消耗点也在这条链上：反序列化超大 JSON、在过滤器里查库、Service 里的远程调用、N+1 查询、序列化循环引用。给每一段加计时日志，能明确指出慢在哪一环，比笼统地说接口慢有用得多。' },
      { h: '12.9 用 curl 与日志排查' },
      { p: '启动后默认 8080 端口。用 curl 验证增删查改，先看状态码再看响应体；POST 时设置 Content-Type: application/json。' },
      { code: 'curl localhost:8080/api/books\ncurl localhost:8080/api/books/1\ncurl -X POST localhost:8080/api/books \\\n  -H "Content-Type: application/json" \\\n  -d \'{"title":"Java","author":"Tom","price":59}\'\ncurl -X DELETE localhost:8080/api/books/1', title: 'curl' },
      { p: '接口不通先看三件事：服务是否启动、端口是否对、路径是否含 context-path。启动日志里有一行 Tomcat started on port，确认端口后再发请求。404 多半是路径或组件扫描问题，Connection refused 才是服务没起来。' },
      { p: 'curl 要带全信息。-i 看响应头，-v 看握手和请求头，-X 指定方法，-H 设置 Content-Type，-d 传请求体。POST 忘了 Content-Type: application/json 时，Spring 会返回 415，这个错误信息很明确，照着改即可。' },
      { p: '400 通常是参数绑定失败，响应体里会说明哪个字段不合法；500 要看服务端日志堆栈的第一行，那才是根因，后面的行是调用链。把日志级别调到 DEBUG 可以打印 SQL 和绑定过程，但排查完要调回去，否则日志量会拖慢系统。' },
      { p: '用 Postman 或浏览器插件也可以，但 curl 的好处是可复制、可写进脚本、可在服务器上直接执行。把常用请求保存成一个 shell 脚本，每次改完代码跑一遍，比手工点界面可靠，也方便在提交前做一次冒烟测试。' },
      { p: '日志要能串起来。给每个请求生成一个请求 id，放进响应头和日志，用户报错时提供这个 id，就能直接定位到那一次请求的完整链路。这个习惯在单体阶段看似多余，拆成多个服务后是排查的救命稻草。' },
      { p: '检查返回内容时用 jq 格式化，一眼能看出结构对不对：jq . 展开全部字段，jq .data 只看数据部分，jq keys 看有哪些键。接口返回一大段压缩 JSON 时，肉眼比对字段很容易漏，工具几秒钟就能确认。' },
      { h: '12.10 常见错误与排查顺序' },
      { list: ['Controller 里 new Service，绕过 Spring 容器，事务和注入失效。', 'POST 忘记 @RequestBody，收到对象字段全是 null。', '端口被占用启动失败，改 server.port 或结束占用进程。', '实体没有无参构造器，JPA 反射创建失败。', '异常没有统一处理，前端收到 HTML 错误页。'] },
      { p: '404 先看路径和方法有没有写对、组件扫描有没有覆盖、context-path 是否与请求一致。Spring 6 默认不打印映射表，可以打开 debug 日志或使用 actuator 的 mappings 端点确认接口是否注册成功。' },
      { p: '405 是路径对但方法不对，例如用 GET 调用了只支持 POST 的接口。响应头里的 Allow 会列出支持的方法，照着改请求即可，不用去翻代码。' },
      { p: '415 是 Content-Type 不匹配，最常见的是 POST 少写了 application/json。406 是 Accept 与返回类型不匹配，出现得少，但出现时同样先检查请求头。' },
      { p: '500 且堆栈是 LazyInitializationException，说明在事务外访问了懒加载关联。改成在事务内取需要的数据，或者用 DTO 投影，不要为了省事打开 open-in-view，那只是把问题藏起来。' },
      { p: '500 且日志里出现大量相似 SQL，通常是 N+1：循环里逐条查关联对象。用 JOIN FETCH 或 @EntityGraph 一次取出，或者先批量查主表再在内存里按 id 组装，两种方式都能把查询次数降下来。' },
      { p: '返回 JSON 时报无限递归，是双向关联互相引用。用 @JsonIgnore 或 @JsonManagedReference 打断，或者干脆返回 DTO。实体直接当响应时这个问题特别常见，也是加 DTO 的又一条理由。' },
      { h: '12.11 测试：MockMvc 与分层测试' },
      { p: '测试分三层：Repository 测试用 @DataJpaTest，配 H2 内存库，验证查询方法；Service 测试用普通 JUnit 加 Mockito，把 Repository 换成 mock，验证业务规则；Controller 测试用 @WebMvcTest 加 MockMvc，验证路径、参数绑定、状态码和 JSON 结构。' },
      { p: 'MockMvc 的写法是 perform 一个请求，然后 andExpect 状态码、内容类型、JSON 路径的值。它不启动真实服务器，速度快，适合提交前跑。真正的端到端测试用 @SpringBootTest 加 TestRestTemplate，数量要少，只覆盖关键链路。' },
      { p: '测试数据要独立。每个测试方法自己准备数据，不要依赖上一个方法留下的状态；用 @Transactional 让测试结束后自动回滚，或者用 @DirtiesContext 重建上下文。测试之间互相依赖，最终会变成只能整体跑、单独跑就失败的套件。' },
      { p: '断言要具体。断言列表大小等于 2 比断言不为空有用；断言错误码是 BOOK_NOT_FOUND 比只断言状态码 404 更能防止回归。测试也是文档，写清楚为什么期望这个结果，后来的人才知道能不能改。' },
      { p: '不要为了覆盖率写测试。一个把所有分支都点一遍但不断言结果的测试，除了拖慢构建没有任何价值。优先覆盖业务规则、边界条件和曾经出过 bug 的地方，这三处的投入回报最高。' },
      { p: '测试方法名要写清场景和期望，例如 createBook_shouldReturn400_whenPriceNegative。一个方法只验证一个行为，失败时不用猜是哪条规则坏了；测试类与被测类同名同包，找起来最快，也方便对照覆盖率报告。' },
      { p: '构造测试数据用 builder 或工厂方法，不要在几十个测试里重复写七八行 set。数据只写和当前用例相关的字段，其余用默认值，这样测试失败时一眼能看出是哪个字段导致了问题。' },
      { h: '12.12 部署与配置分离' },
      { p: 'mvn package 打出可执行 jar，java -jar target/demo-0.0.1-SNAPSHOT.jar 启动。配置用 application.yml 或环境变量区分开发/生产；容器化用 eclipse-temurin 基础镜像。' },
      { p: 'mvn package 之后 target 下会有可执行 jar，内部已经包含内嵌 Tomcat，不需要单独安装容器。java -jar 启动时可以用 --server.port=9090 覆盖配置，也可以设置 SPRING_PROFILES_ACTIVE 切换环境。' },
      { p: '配置文件按环境拆分：application.yml 放公共项，application-dev.yml 和 application-prod.yml 放差异项。生产环境的数据库密码用环境变量注入，不要提交到仓库；容器部署时用 Secret 或配置中心，权限控制要和代码仓库分开。' },
      { p: '日志要落到文件并切割，容器里则输出到标准输出由平台收集。健康检查用 actuator 的 /actuator/health，就绪和存活探针分开配置，避免应用还没连上数据库就被流量打到。' },
      { p: '上线前检查三件事：数据库迁移脚本是否执行、接口是否做了幂等、回滚方案是否可用。能回滚才敢发布，这句话对单体应用和微服务同样成立，先想好怎么退，再考虑怎么进。' },
      { p: '部署之后要做一次真实冒烟：用 curl 走一遍创建、查询、删除，确认数据库里确实有了数据，再去看监控的响应时间和错误率。只看启动日志没有报错就宣布上线，是很多事故的共同起点。' },
      { p: '容器化时把依赖下载与源码编译分层，先复制 pom 再复制源码，能复用镜像层缓存，构建时间会明显缩短。镜像里只放 jar 和启动脚本，不要塞进源码和测试报告，体积越小，拉取和扩容越快。' },
      { p: 'Spring Boot 用 application.yml 管理配置，支持多环境 profile：application-dev.yml、application-prod.yml。启动时用 --spring.profiles.active=prod 选择，敏感信息用环境变量注入，不要提交到 Git。' },
      { code: 'server:\n  port: 8080\nspring:\n  datasource:\n    url: ${DB_URL:jdbc:mysql://localhost:3306/demo}\n    username: ${DB_USER:root}\n    password: ${DB_PASSWORD:}\n  jpa:\n    hibernate:\n      ddl-auto: update', title: 'application.yml' },
      { p: '配置优先级大致是：命令行参数 > 环境变量 > application-{profile}.yml > application.yml。排查“配置没生效”时，先看启动日志里的 active profile，再确认键名和缩进。' },
      { h: '本章小结' },
      { list: ['Spring Boot = 自动配置 + 内嵌容器 + Starter 依赖。', 'Controller 薄、Service 厚、Repository 只做数据访问。', 'REST 用对 HTTP 方法和状态码，JSON 由 Jackson 转换。', '异常统一处理，打包成可执行 jar 部署。'] },
      { h: '常见追问' },
      { list: [
        '<b>问：Controller 里能不能直接写业务逻辑？</b><br>答：不能。Controller 只负责收参数、调 Service、包响应；业务规则、事务边界和校验顺序都放 Service。原因很实际：事务靠代理织入，业务写在 Controller 上容易出现「明明标了 @Transactional 却不回滚」；而且 Controller 一旦掺杂规则，测一个业务分支就得起整个 Web 上下文，既慢又难断言。参数形状的校验留在 Controller，业务语义的校验留在 Service，边界才清楚。',
        '<b>问：为什么用 DTO 而不是直接把 Entity 返回给前端？</b><br>答：Entity 跟着表结构变，DTO 跟着接口契约变。混用之后，一次字段改名就是一次接口不兼容，前端要么报错要么静默少拿到字段；更麻烦的是 Entity 上常有密码、内部状态、关联对象这类不该外露的字段，序列化时一起吐出去就是信息泄漏。DTO 还能承载接口需要而表里没有的字段，比如把金额从分转成元、把状态码翻成中文，转换只发生在 Controller 或专门的转换方法里，改动范围可控。',
        '<b>问：事务注解为什么有时不生效？</b><br>答：因为 @Transactional 靠代理生效：同类内部方法自调用、private 方法、自己 new 出来的对象都不走代理，注解等于没写。另一类原因是异常被吞：方法里 try/catch 把异常吃掉，代理看不到异常自然不会回滚；默认也只对 RuntimeException 和 Error 回滚，受检异常要显式写 rollbackFor。剩下的原因包括类没被容器管理、方法不是 public、数据库引擎不支持事务，排查时按「有没有代理、有没有异常、异常类型对不对」三步走最快。'
      ] },
      { h: '自测与练习' },
      { p: '先自己动手做一遍，再展开参考答案对照预期现象与判断依据。' },
      { ol: [
        '增加「按书名模糊查询」和「修改价格」两个接口。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：按书名搜索只返回书名包含关键词的记录，关键词为空或超长时返回 400；改价传负数返回 400，传合法值返回 200，再查价格已变，改不存在的 id 返回 404。<b>为什么</b>：模糊查询的语义在 Service，接口只负责搬参数；改价是写操作，要有事务、校验和记录不存在的分支。<b>要点</b>：Controller 用 <code>@RequestParam(required = false)</code> 接关键词，Service 里交给 <code>findByTitleContaining</code>；改价方法标 <code>@Transactional</code>，先 <code>findById(id).orElseThrow()</code> 再改字段，提交时靠脏检查落库。</div></details>',
        '用 Bean Validation 的 @NotBlank/@Min 校验请求参数。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：请求体缺书名或价格传负数时返回 400，响应里带字段名和自定义消息；参数合法时正常落库，库里不会出现空书名。<b>为什么</b>：校验声明在 DTO 上并由 @Valid 触发，比在每个方法里手写 if 更不容易漏，错误也能被统一异常处理收拢成固定格式。<b>要点</b>：DTO 字段加 <code>@NotBlank(message = "书名不能为空")</code> 和 <code>@Min(value = 0)</code>，Controller 参数前加 <code>@Valid</code>；用 <code>@RestControllerAdvice</code> 捕获 MethodArgumentNotValidException，把字段名与消息拼进统一响应体。</div></details>',
        '把 H2 内存库换成 MySQL，配置连接池和 JPA 方言。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：应用能连上本地 MySQL，启动日志出现 HikariPool 初始化，重启后数据仍在；连接串写错时启动阶段就报错，而不是等第一次查询才失败。<b>为什么</b>：换库变的是驱动、URL、方言三样，其余代码不用动，这正是分层的价值；连接池参数决定并发下的表现。<b>要点</b>：pom 加 <code>com.mysql:mysql-connector-j</code>（runtime 范围），application.yml 配 <code>jdbc:mysql://localhost:3306/lab?useSSL=false&amp;serverTimezone=UTC</code>、用户名密码，并设 <code>spring.jpa.hibernate.ddl-auto=none</code>，方言交给 Hibernate 自动识别。</div></details>',
        '给 Controller 写 MockMvc 测试，分别验证正常查询返回 200、参数非法返回 400、资源不存在返回 404。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：三个用例分别得到 200、400、404；400 的响应体里能读到校验消息，404 时返回统一的错误结构而不是默认异常页。<b>为什么</b>：Controller 测试只关心路由、参数绑定、状态码和响应结构，用 MockMvc 不启真实端口，一次几百毫秒，适合每次提交都跑。<b>要点</b>：<code>@WebMvcTest(BookController.class)</code> 配 <code>@MockBean BookService</code> 隔离业务；用 <code>mockMvc.perform(get("/books/99")).andExpect(status().isNotFound())</code>；返回体用 <code>jsonPath("$.message")</code> 断言，别去比整串。</div></details>'
      ] }
    ]
  };

  T['sql-basics'] = {
    meta: '本章约 5200 字 · 建议 35 分钟 · 配套流程图与 3 道习题',
    blocks: [
      { h: '13.1 数据库、表、行、列：先把名词对上' },
      { p: '关系型数据库把数据放在表里。一张表描述一类事物（图书、用户、订单），一行是一条记录，一列是一个字段。主键唯一标识一行，通常自增；外键用来关联另一张表。' },
      { table: { head: ['概念', '含义', '例子'], rows: [
        ['表 table', '一类数据的集合', 'book'],
        ['行 row', '一条记录', '一本具体的书'],
        ['列 column', '一个字段', 'title、price'],
        ['主键 primary key', '唯一标识一行', 'id'],
        ['外键 foreign key', '关联另一张表', 'order.book_id']
      ] } },
      { h: '13.2 建表：字段类型、主键与自增' },
      { p: '建表先定字段类型。整数用 INT 或 BIGINT，金额用 DECIMAL(10,2) 而不是 FLOAT，字符串用 VARCHAR 并给出合理长度，时间用 DATETIME 或 TIMESTAMP，布尔用 TINYINT(1)。类型选错后期迁移代价很高，金额用浮点会出现 0.1 加 0.2 不等于 0.3 的精度问题。' },
      { p: '主键用自增整数最省事，插入时不用管 id，数据库保证唯一。分布式场景才考虑 UUID 或雪花 id，因为自增在分库分表时会冲突。主键一旦确定就不要改，外键、缓存和前端路由都可能依赖它。' },
      { p: '建表语句要写清默认值和非空约束。created_at 设 DEFAULT CURRENT_TIMESTAMP，status 设 DEFAULT 0，能减少插入时漏字段。NOT NULL 要在建表时就加，等数据脏了再补约束，清洗成本会高很多。' },
      { p: '字符集统一用 utf8mb4，排序规则统一，否则中文和 emoji 会出现截断或乱码。表名和字段名用小写下划线，避开关键字，可移植性更好，也不会因为某个数据库的关键字列表不同而换库失败。' },
      { p: '索引和约束在建表时一起规划。主键、唯一键、外键至少要有，常用查询条件对应的索引也应在建表脚本里体现。后期用 ALTER 加索引在大表上可能锁表，提前想清楚比事后补救便宜。' },
      { p: '建表时要为每一列选择合适的数据类型：整数用 INT/BIGINT，金额用 DECIMAL，字符串用 VARCHAR/CHAR，时间用 DATETIME/TIMESTAMP。类型选得过大浪费空间，选得过小会截断或溢出。' },
      { table: { head: ['类型', '用途', '注意'], rows: [
        ['INT / BIGINT', '整数、主键', '主键常用 BIGINT 防溢出'],
        ['DECIMAL(p,s)', '金额、精确小数', '不要用 FLOAT/DOUBLE 存金额'],
        ['VARCHAR(n)', '变长字符串', 'n 是字符数，不是字节数'],
        ['DATETIME', '日期时间', '不带时区；跨时区用 TIMESTAMP'],
        ['TINYINT', '布尔/小整数', '0/1 表示 false/true']
      ] } },
      { h: '13.3 SELECT 与 WHERE：挑列与筛行' },
      { p: 'SELECT 选择列，FROM 指定表，WHERE 过滤行。生产环境尽量写明列名，不要用 SELECT *，避免多余数据传输和列顺序变化。' },
      { code: 'SELECT id, title, price\nFROM book\nWHERE price > 50 AND author = \'Tom\';', title: 'query.sql' },
      { p: 'WHERE 支持比较、BETWEEN、IN、LIKE、IS NULL、AND/OR。LIKE 中 % 匹配任意字符，_ 匹配一个字符；以 % 开头的模糊查询通常用不上索引。' },
      { h: '13.4 排序、去重、分页与聚合' },
      { p: 'ORDER BY 排序，ASC 升序（默认）、DESC 降序；DISTINCT 去重；LIMIT offset, size 分页。分页页码从 0 开始时 offset = page × size。' },
      { code: 'SELECT DISTINCT author FROM book ORDER BY author ASC;\n\nSELECT id, title, price\nFROM book\nORDER BY price DESC\nLIMIT 0, 10;', title: 'sort.sql' },
            { p: 'COUNT、SUM、AVG、MAX、MIN 对一组行做统计；GROUP BY 按列分组，HAVING 过滤分组后的结果。WHERE 在分组前过滤，HAVING 在分组后过滤，别混用。' },
      { code: 'SELECT author, COUNT(*) AS cnt, AVG(price) AS avg_price\nFROM book\nGROUP BY author\nHAVING COUNT(*) >= 2\nORDER BY cnt DESC;', title: 'group.sql' },
      { h: '13.5 查询的执行顺序' },
      { p: 'SQL 的书写顺序和执行顺序不一样。书写是 SELECT、FROM、WHERE、GROUP BY、HAVING、ORDER BY、LIMIT；实际执行大致是 FROM 找表、WHERE 过滤行、GROUP BY 分组、HAVING 过滤组、SELECT 计算列、ORDER BY 排序、LIMIT 截断。' },
      { p: '理解这个顺序能解释很多为什么报错。WHERE 里不能用 SELECT 中定义的别名，因为 WHERE 执行时别名还不存在；ORDER BY 可以用别名，因为它最后执行。聚合函数不能写在 WHERE 里，只能写在 HAVING 或 SELECT 里。' },
      { p: '另一个推论是 LIMIT 最后生效，所以 LIMIT 10 不是先取十行再排序，而是排序完取前十。深度分页 LIMIT 100000, 20 会扫描并丢弃十万行，越翻越慢，应该改用游标分页，记住上一页最后一行的 id，用 WHERE id > ? 继续取。' },
      { p: '知道执行顺序，优化就有方向：让 WHERE 尽早过滤掉数据，避免在列上套函数导致索引失效，把大排序改成利用索引顺序。EXPLAIN 里的 rows 估算值，就是优化器对每一阶段行数的判断。' },
      { p: '还有一个常见误解：SELECT 的列在 GROUP BY 之后计算，所以 SELECT 里可以写聚合函数，而 WHERE 里不行。分不清这一点，写分组查询时会反复试错，其实记住执行顺序就能推导出来。' },
      { p: 'DISTINCT 作用于 SELECT 的全部列，而不是紧跟在它后面的那一列。写 SELECT DISTINCT author, price 时，去重的是作者和价格的组合，不是作者。想要每个作者一条，应该用 GROUP BY，语义更清楚，也更容易扩展。' },
      { h: '13.6 增删改：三句最危险的语句' },
      { p: 'INSERT 新增一行，UPDATE 修改满足条件的行，DELETE 删除满足条件的行。UPDATE/DELETE 不带 WHERE 会作用于全表，这是线上最危险的误操作。' },
      { code: 'INSERT INTO book(title, author, price) VALUES (\'Java\', \'Tom\', 59.0);\n\nUPDATE book SET price = 49.0 WHERE id = 1;\n\nDELETE FROM book WHERE id = 2;', title: 'crud.sql' },
      { note: '<b>安全习惯：</b>写 UPDATE/DELETE 时先写 WHERE，再补前面的语句；执行前用同样的 WHERE 写 SELECT，确认影响范围。' },
      { h: '13.7 多表查询：JOIN 类型与笛卡尔积' },
      { p: 'JOIN 按关联字段把两张表组合成一张结果表。INNER JOIN 只保留匹配行；LEFT JOIN 保留左表全部行，右表没匹配补 NULL。' },
      { code: 'SELECT b.title, a.name AS author_name\nFROM book b\nJOIN author a ON b.author_id = a.id\nWHERE a.name = \'Tom\';', title: 'join.sql' },
      { p: 'JOIN 的本质是按条件匹配两张表的行。不加 ON 条件会得到笛卡尔积，两张各一千行的表会产生一百万行，既慢又错。写 JOIN 时先写 ON，再写 SELECT，可以避免漏条件。' },
      { p: 'INNER JOIN 只保留两边都匹配的行；LEFT JOIN 保留左表全部行，右表缺失补 NULL；RIGHT JOIN 相反；FULL JOIN 在 MySQL 里要用 UNION 模拟。统计每个作者有多少本书，包括没写过书的作者，必须用 LEFT JOIN，用 INNER JOIN 会漏掉零本的人。' },
      { p: '一对多关联会导致行数膨胀。一本书有多个标签时，JOIN 之后按书统计会重复计数，需要 COUNT(DISTINCT book_id)。多张一对多表同时 JOIN 会得到乘积，应该分两次查询或在应用层聚合。' },
      { p: 'JOIN 的列要有索引，通常是外键列和被驱动表的主键。EXPLAIN 里如果出现全表扫描加 Using join buffer，说明关联列没走索引，数据量一大就会明显变慢。' },
      { p: '同一张表也能 JOIN 自己，这叫自连接。查每个员工及其直属上级的姓名时，把员工表分别命名为 e 和 m，用 e.manager_id 等于 m.id 关联。自连接必须起不同别名，否则数据库分不清你指的是哪一份。' },
      { p: '连接条件写在 ON 里还是 WHERE 里，对 INNER JOIN 结果相同，对 LEFT JOIN 完全不同。写到 WHERE 里会把外连接变成内连接，因为 NULL 行会被条件过滤掉。这是外连接最常见的错误，写完后检查一下条件位置。' },
      { h: '13.8 子查询与 EXISTS' },
      { p: '子查询可以出现在 WHERE、FROM 和 SELECT 里。WHERE 里的标量子查询返回单值，IN 子查询返回一列，EXISTS 判断是否存在。选哪种取决于语义和数据量，不取决于个人喜好。' },
      { p: 'IN 适合小结果集，NOT IN 遇到 NULL 会整体返回空，这是经典陷阱：子查询结果里只要有一个 NULL，x NOT IN 的结果既不是真也不是假。改用 NOT EXISTS 可以避开这个问题。' },
      { p: 'EXISTS 只关心有没有行，找到一条就能停止，关联子查询在数据量大时通常比 IN 更稳。但优化器会做改写，实际性能要看执行计划，不要凭经验下结论。' },
      { p: '子查询嵌套超过两层就该考虑用 JOIN 或临时表重写。层层嵌套的 SQL 难以阅读和优化，也容易在不同数据库之间出现行为差异。' },
      { p: 'FROM 里的子查询叫派生表，必须给别名，执行时会先物化或合并。数据量大时派生表可能产生临时表，EXPLAIN 里出现 Using temporary 就要留意，必要时改成先建临时表再加索引。' },
      { h: '13.9 NULL 的陷阱：三值逻辑' },
      { p: 'NULL 表示未知，不是 0，也不是空字符串。任何与 NULL 的比较结果都是 UNKNOWN，WHERE 只保留结果为真的行，所以 price = NULL 永远查不到东西，必须写 price IS NULL。' },
      { p: '聚合函数会忽略 NULL。COUNT(price) 统计的是价格非空的行数，COUNT(*) 才是总行数；AVG 的分母也排除了 NULL，这与直觉不同，统计口径要提前说清楚，否则报表数字对不上。' },
      { p: '排序时 NULL 的位置由数据库决定，MySQL 升序把 NULL 排在最前，降序排在最后。需要固定顺序就显式写 ORDER BY price IS NULL, price，让空值集中在一端。' },
      { p: '建表时尽量给常用列加 NOT NULL 和默认值，把未知变成明确的业务状态，能避免大量三值逻辑带来的判断错误。必须允许空时，在 Java 里用 Optional 或包装类型接收，不要用基本类型，否则会静默变成 0。' },
      { p: '字符串拼接遇到 NULL 也会整体变成 NULL。用 CONCAT 时先判空或用 COALESCE 给默认值，展示层才不会出现空白。这个细节在拼地址、拼姓名时特别容易翻车。' },
      { p: '统计去重人数时 COUNT(DISTINCT user_id) 与 COUNT(user_id) 差别很大，前者排除重复和 NULL，后者只排除 NULL。报表口径要写进字段注释，否则两个人查同一张表得出不同数字，谁也说不清谁对。' },
      { h: '13.10 主键、索引与约束' },
      { p: '主键唯一且非空，数据库通常自动建索引。索引像书的目录，加速查询但降低写入速度；经常出现在 WHERE、JOIN、ORDER BY 的列适合建索引，低选择性字段（性别）不值得。' },
      { table: { head: ['约束', '作用'], rows: [
        ['PRIMARY KEY', '唯一标识一行，非空'],
        ['UNIQUE', '该列值不能重复'],
        ['NOT NULL', '该列不能为空'],
        ['FOREIGN KEY', '值必须存在于关联表'],
        ['CHECK', '值必须满足条件']
      ] } },
      { h: '13.11 索引与执行计划' },
      { p: '索引是排好序的辅助结构，最常见的是 B+ 树。它能快速定位范围，也能避免排序。主键自带聚簇索引，二级索引的叶子节点存的是主键值，所以通过二级索引查其他列需要回表。' },
      { p: '联合索引遵循最左前缀。索引 (a, b, c) 能支持 a、a 加 b、a 加 b 加 c 的查询，不能支持只查 b。范围查询会中断后面的列，例如 a 等于 1 且 b 大于 2 且 c 等于 3 时，c 用不上索引。' },
      { p: '在列上做函数、类型转换、前导模糊匹配都会让索引失效。WHERE DATE(created_at) 等于某天，改成范围比较 created_at 大于等于当天且小于次日，才能走索引。' },
      { p: '用 EXPLAIN 看执行计划：type 至少要到 range，key 显示实际使用的索引，rows 是预估扫描行数，Extra 里出现 Using filesort 或 Using temporary 说明有额外排序或临时表。优化前后对比这几项，比凭感觉改快慢更可靠。' },
      { p: '索引不是越多越好。每个索引都会增加写入成本、占用磁盘，也会让优化器在多索引之间犹豫。给高频且选择性高的查询建索引，定期检查没用到的索引并清理，比盲目堆索引有效。' },
      { p: '只查索引里已有的列时，数据库可以直接从索引返回结果，不需要回表，这叫覆盖索引。把查询列和条件列放进同一个联合索引，往往比加好几个单列索引更有效。EXPLAIN 的 Extra 出现 Using index，就说明走上了覆盖索引。' },
      { p: '用 EXPLAIN 看执行计划：type 从好到差大致是 system/const/eq_ref/ref/range/index/ALL；key 是实际使用的索引；rows 是预估扫描行数。出现 ALL 且 rows 很大，通常需要加索引或改写查询。' },
      { code: 'EXPLAIN SELECT * FROM book WHERE author = \'Tom\' AND price > 50;\nCREATE INDEX idx_author_price ON book(author, price);', title: 'index.sql' },
      { h: '13.12 事务与隔离级别' },
      { p: '事务是一组要么全成功要么全失败的操作。转账是典型例子：扣款和入账必须在一起，中间失败就回滚。MySQL 的 InnoDB 支持事务，MyISAM 不支持，选引擎时要注意。' },
      { p: 'ACID 四个特性里，隔离性最容易出问题。读未提交会脏读，读已提交解决脏读但有不可重复读，可重复读解决不可重复读但可能幻读，串行化最安全但并发最差。MySQL 默认是可重复读，并通过间隙锁在一定程度上避免幻读。' },
      { p: '并发更新要用行锁或乐观锁。SELECT 加 FOR UPDATE 会锁住选中的行，适合库存扣减；乐观锁用版本号，更新时带 WHERE version 等于旧值，影响行数为 0 说明被别人改过，需要重试。' },
      { p: '事务要短。长事务持有锁，阻塞其他请求，还会让 undo 日志膨胀。把查询、远程调用放到事务外，只把必须原子化的写操作包进来，是控制事务时长最有效的办法。' },
      { p: '死锁不是异常，是并发系统的正常现象。数据库检测到死锁会回滚其中一个事务，应用要能捕获并重试。减少死锁的办法是统一加锁顺序、缩短事务、给更新条件加索引，而不是简单地提高重试次数。' },
      { p: '隔离级别从低到高：READ UNCOMMITTED（可能脏读）、READ COMMITTED（避免脏读）、REPEATABLE READ（避免不可重复读，MySQL 默认）、SERIALIZABLE（避免幻读，但并发最差）。级别越高，一致性越强，吞吐越低。' },
      { code: 'START TRANSACTION;\nUPDATE account SET balance = balance - 100 WHERE id = 1;\nUPDATE account SET balance = balance + 100 WHERE id = 2;\nCOMMIT;\n-- 出错时 ROLLBACK;', title: 'transaction.sql' },
      { h: '13.13 SQL 注入与 JDBC：把参数交给占位符' },
      { p: '把用户输入拼进 SQL 会产生注入。例如输入 <code>\' OR \'1\'=\'1</code> 可能让条件永真。Java 里用 PreparedStatement 的 ? 占位符，参数只作为值传入，不参与语法解析。' },
      { p: 'JDBC 的固定流程是：加载驱动（新版本可省略）、建立连接、创建 PreparedStatement、设置参数、执行、遍历 ResultSet、关闭资源。连接、语句、结果集都要关闭，用 try-with-resources 最省心。' },
      { p: '永远用问号占位符传参，不要拼字符串。PreparedStatement 会把参数当作值发送，不做语法解析，从根本上阻断注入。动态表名、列名不能用占位符，只能白名单校验后拼接。' },
      { p: '批量插入用 addBatch 和 executeBatch，比循环单条插入快一个数量级。记得关闭自动提交并显式提交，失败时回滚，否则一半数据进去、一半没进去，比全失败更难清理。' },
      { p: '连接是稀缺资源，生产环境一定用连接池，不要每次请求都新建连接。连接池要配置最大连接数、超时和泄漏检测，否则慢查询会耗尽连接，表现为所有接口一起超时。' },
      { p: '分页查询通常要两条 SQL：一条 COUNT 总数，一条带 LIMIT 取当前页。总数可以缓存或估算，但翻页数据必须实时。两条 SQL 的条件必须完全一致，否则会出现总数一百、翻到第五页却空白这种对不上的情况。' },
      { p: '查询结果映射成对象时注意类型。数据库的 DECIMAL 用 BigDecimal 接，DATETIME 用 LocalDateTime 接，TINYINT 用 Boolean 或 Integer 接，不要一律用 String 再自己转，转错时异常往往出现在很远的地方。' },
      { h: '13.14 从 SQL 到 Java 的映射' },
      { p: '数据库里的表和 Java 里的类通常一一对应：一行数据映射成一个对象，一列映射成一个字段。查询结果用 ResultSet 逐行读取，或者交给 MyBatis/JPA 自动映射。理解这层映射，才能看懂 ORM 框架在做什么。' },
      { list: ['表名 → 类名，列名 → 字段名（下划线转驼峰）。', '主键 → id 字段，类型用 Long/Integer。', 'DECIMAL → BigDecimal，DATETIME → LocalDateTime。', '外键 → 对象引用或单独的 id 字段。', '一对多 → List<子对象>，多对多 → 中间表实体。'] },
      { h: '13.15 常见错误与排查' },
      { p: '报错 Unknown column 多半是字段名拼错或表别名没写对；报错 Table doesn\'t exist 先确认连的是哪个库，USE 一下再执行。库名和表名大小写在不同操作系统上行为不同，部署到 Linux 后突然找不到表，通常是这个原因。' },
      { p: '查询结果比预期少，检查 WHERE 里的 AND 和 OR 优先级。AND 优先级高于 OR，a 等于 1 或 b 等于 2 且 c 等于 3 等价于 a 等于 1 或 b 等于 2 且 c 等于 3，需要括号时一定要写。' },
      { p: '更新影响行数为 0 不一定是失败：值没有变化时 MySQL 也返回 0。判断是否命中要先用 SELECT 确认，或者比较受影响行数与匹配行数，不要看到 0 就以为条件写错了。' },
      { p: '中文乱码依次检查连接串的 characterEncoding、库表字符集和客户端编码，三处必须一致。只改一处往往看起来好了，换一个客户端又乱，根因是链路里还有一处使用默认编码。' },
      { p: '慢查询先用日志找出具体 SQL，再用 EXPLAIN 看执行计划，最后才考虑加索引或改写。跳过前两步直接加索引，经常加了用不上，还拖慢了写入。' },
      { h: '13.16 一次慢查询的排查实录' },
      { p: '场景：订单列表页打开要三秒。表里有五十万订单、二十万用户，页面支持按用户手机号搜索并按时间倒序。功能没问题，慢在查询，这类问题靠猜是猜不出来的，需要按固定步骤定位。' },
      { p: '第一步开慢查询日志，找到真正执行的 SQL。日志里的语句形如从订单表关联用户表，按手机号过滤，按创建时间倒序取前二十条。拿到原文后不要急着改，先确认它是不是页面实际发出的那条，参数不同计划可能不同。' },
      { p: '第二步用 EXPLAIN 看计划。用户表在手机号列上是全表扫描，预估扫描二十万行；订单表也是全表扫描，Extra 里出现 Using filesort，说明排序没有用上索引。两处问题叠加，三秒的耗时就有了来源。' },
      { p: '第三步加索引。用户表手机号建唯一索引，订单表建 user_id 加 created_at 的联合索引。再看计划，用户表变成常量查找，订单表用上了联合索引，但排序仍然存在，因为排序发生在关联之后，作用的是关联结果。' },
      { p: '第四步改写语句：先用手机号查出用户 id，再用 WHERE user_id 等于该 id 且 ORDER BY created_at DESC 取前二十。联合索引同时满足过滤和排序，filesort 消失，扫描行数从二十万降到二十。' },
      { p: '第五步验证并记录。响应时间从三秒降到三十毫秒，写入没有明显变慢；把改前改后的执行计划、索引定义和结论写进文档，下次遇到类似问题可以直接复用，而不是重新试一遍。' },
      { h: '13.17 表设计：三范式与三条经验' },
      { p: '第一范式：每列不可再分；第二范式：非主键列完全依赖主键；第三范式：非主键列不依赖其他非主键列。实际项目会在范式与查询性能之间权衡，适度冗余（如订单快照）是允许的。' },
      { list: ['一表一职责，不要把用户、订单、商品塞进一张表。', '主键用无业务含义的自增/雪花 ID，避免业务变更。', '金额用 DECIMAL，时间用统一时区，状态用枚举/字典表。', '为高频查询建索引，但不要给每个列都建。', '删除用软删除（deleted 标记）还是物理删除，要提前约定。'] },
      { p: '第一，字段尽量非空并有默认值。空值会让查询、排序、聚合都多一层判断，也会让索引统计失真。确实需要表达未知时，用一个明确的业务状态代替 NULL，比在三值逻辑里绕来绕去清楚。' },
      { p: '第二，状态字段用短整型或单独的枚举表，不要直接存中文。中文占空间、难比较，改文案还要改数据。存 0、1、2 并在代码或字典表里映射含义，展示层再翻译成用户看得懂的文字。' },
      { p: '第三，时间字段统一存 UTC，展示时按用户时区转换。服务器、数据库、应用三处时区不一致，是时间相关 bug 的主要来源；统一存 UTC 后，跨时区部署也不会出现差八小时的问题。' },
      { p: '第四，命名统一。表名用复数或单数都行，但要全库一致；外键统一叫带表名前缀的 id 字段；布尔字段用 is_ 开头。命名混乱的项目，写 JOIN 时光看字段名根本判断不出该连哪张表。' },
      { p: '第五，软删除要统一。用 deleted_at 记录删除时间，所有查询默认过滤，并为常用查询建带该列的联合索引。只在一半的表上加软删除，比完全不用更难维护，因为没人说得清哪些查询该带条件。' },
      { h: '13.18 综合案例：小型图书库的表设计' },
      { p: '假设要做图书借阅系统，至少需要三张表：book（图书）、reader（读者）、borrow（借阅记录）。borrow 表保存 book_id、reader_id、借出时间、归还时间，通过外键关联另外两张表。这样一本书可以被多次借阅，历史记录不会丢。' },
      { code: 'CREATE TABLE book (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  title VARCHAR(100) NOT NULL,\n  author VARCHAR(50),\n  price DECIMAL(10,2) NOT NULL\n);\n\nCREATE TABLE reader (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  name VARCHAR(50) NOT NULL\n);\n\nCREATE TABLE borrow (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  book_id BIGINT NOT NULL,\n  reader_id BIGINT NOT NULL,\n  borrowed_at DATETIME NOT NULL,\n  returned_at DATETIME NULL,\n  FOREIGN KEY (book_id) REFERENCES book(id),\n  FOREIGN KEY (reader_id) REFERENCES reader(id)\n);', title: 'schema.sql' },
      { p: '设计时先想清楚“哪些数据会重复、哪些关系是一对多”。借阅记录是典型的多对多中间表；如果把借阅人直接塞进 book 表，历史记录会被覆盖，也无法统计借阅次数。' },
      { p: '建表只是第一步，真正决定系统能否长期运行的是约束、索引和事务边界。把这三件事在设计阶段定清楚，后面写 Java 代码会顺利很多。' },
      { h: '13.19 综合练习：把本章知识串起来' },
      { p: '这一节不给新知识点，只把前面的内容串成一条能跑通的练习线。目标是从空库开始，建两张表、造一批数据、写五条查询，再用 JDBC 在 Java 里执行其中一条，最后按清单验收。全部做完，本章的语法才算真正落地。' },
      { p: '第一步建库建表。创建 library 库并指定 utf8mb4；author 表两个字段，id 自增主键、name 非空唯一；book 表五个字段，id 自增主键、title 非空、author_id 非空并加外键指向 author、price 用 DECIMAL、created_at 默认当前时间。再给 book 的 author_id 和 price 各建一个索引，供后面的查询和关联使用。' },
      { p: '第二步造数据。先插三位作者，再插八本书，顺序不能反，否则外键约束会拒绝。书名里故意放一条带单引号或百分号的数据，用来检验后面的参数化和模糊查询。插入完用 COUNT 确认行数，再用一条 LEFT JOIN 确认每位作者的书数，避免漏插或重复插。' },
      { p: '第三步写五条查询。第一条按价格区间过滤并降序；第二条按作者分组统计书数和均价，只保留书数大于等于二的组；第三条用 LEFT JOIN 列出所有作者及其书名，没有书的作者书名显示为空；第四条用 NOT EXISTS 找出没有写过书的作者；第五条做分页，每页三条取第二页。每条都先想清楚用哪种连接、过滤放在 WHERE 还是 HAVING。' },
      { p: '第四步用 JDBC 执行第一条查询。加载驱动、建立连接、准备带两个占位符的语句、设置最低价和最高价、执行、遍历结果集打印书名和价格。整个流程放在 try-with-resources 里，连接串显式指定字符集，确认连接在方法结束时关闭，而不是在循环里反复创建。' },
      { p: '第五步验收。分组统计的书数之和应该等于 book 表总行数；LEFT JOIN 的行数应该大于等于 book 行数；NOT EXISTS 的结果加上有书的作者数应该等于作者总数。数字对不上，说明连接条件或多重关联导致了重复或遗漏，回到执行计划找原因。' },
      { p: '索引和约束的命名也要统一。索引常用 idx 开头加表名和列名，唯一索引用 uk 开头，外键用 fk 开头，出问题时看名字就知道它属于哪张表、覆盖哪些列。命名混乱的库，加了索引也不敢删，最后越积越多，写入越来越慢，却没人说得清哪一个可以去掉。' },
      { p: '还要测异常路径：插入重复主键应该报错而不是覆盖；删除还有书的作者应该被外键拦住；价格插成负数在加了检查约束时应该失败。把这些报错信息记下来，以后线上看到同样的提示能立刻判断原因。' },
      { p: '最后做一次性能检查：对五条查询各跑一次 EXPLAIN，确认都走了索引，没有全表扫描和 filesort；把其中一条改成在列上套函数，观察索引失效后扫描行数的变化，再改回来。亲眼见过计划的变化，比记住结论更牢。' },
      { h: '本章小结' },
      { list: ['表、行、列、主键是关系数据库的基本概念。', '查询四件套：SELECT、WHERE、ORDER BY、LIMIT。', '分组统计用 GROUP BY + HAVING，多表用 JOIN。', 'UPDATE/DELETE 必须带 WHERE；Java 用 PreparedStatement 防注入。'] },
      { h: '常见追问' },
      { list: [
        '<b>问：COUNT(*) 和 COUNT(1) 有区别吗？</b><br>答：在主流数据库里没有实质区别，优化器会把 COUNT(1) 当成同一个计划，性能也一致，选哪个看团队习惯。真正的区别在 COUNT(列名)：它只统计该列非 NULL 的行，一列允许为空时结果会小于总行数，这是报表里最容易算错的地方。另外 COUNT 要扫描满足条件的行，大表上并不便宜，需要频繁统计时应该做计数表或用近似统计，而不是每次都翻全表。',
        '<b>问：WHERE 和 HAVING 能互换吗？</b><br>答：语法上有些写法两边都能过，语义上不能换：WHERE 在分组之前过滤行，HAVING 在分组之后过滤组。把聚合条件写进 WHERE 会直接报错，因为那时分组还不存在；把普通列条件写进 HAVING 则会先分组再筛，白白多算一堆组，还容易写成依赖别名的非标准 SQL。判断方法很简单：条件里出现聚合函数就放 HAVING，否则一律放 WHERE。',
        '<b>问：JOIN 和子查询哪个快？</b><br>答：看执行计划，不看计划就是猜。现代优化器常把 IN 子查询改写成半连接，性能与 JOIN 相当；但相关子查询在某些版本里仍会逐行执行，字段上套函数或类型不一致时还会让索引失效。判断顺序是：先 EXPLAIN 看扫描行数和有没有 DEPENDENT SUBQUERY，再把可疑的相关子查询改写成 JOIN 或 EXISTS 对比结果。行数只有几十行的表上纠结这个没有意义。',
        '<b>问：索引越多越好吗？</b><br>答：不是。每个索引都要在 INSERT、UPDATE、DELETE 时维护，写入越频繁代价越明显；索引还占空间、拖慢备份和加字段这类 DDL。该做的是给高频查询建覆盖过滤与排序的联合索引，让一条语句只用一个索引就走完，而不是给每一列都单独建一个。加完必须回头看计划确认用上了，长期没人用的索引要删掉，否则越积越多，写入越来越慢却没人说得清哪一个可以去掉。',
        '<b>问：事务越大越好吗？</b><br>答：正好相反，事务应该尽量短。事务未提交期间持有的锁不释放，其他会话要么等锁要么超时；日志和回滚段持续增长，回滚代价随事务规模上升；长事务还会把主从延迟放大。正确做法是把网络调用、文件读写、用户交互这类耗时动作放到事务外面，只把必须一起成功或一起失败的几条 SQL 包进事务，并给事务设置超时与重试策略。'
      ] },
      { h: '自测与练习' },
      { p: '先自己动手做一遍，再展开参考答案对照预期现象与判断依据。' },
      { ol: [
        '建一张 book 表（id 主键自增、title、author、price），插入 5 条数据。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：建表后 DESC book 能看到四个字段，id 为自增主键；插入五条后 <code>SELECT COUNT(*) FROM book</code> 返回 5，重复插同一个 id 时被主键拦住而不是覆盖。<b>为什么</b>：id 交给自增就不用自己维护唯一键；title 设成 NOT NULL，脏数据在入口就被拒绝。<b>要点</b>：<code>CREATE TABLE book (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(100) NOT NULL, author VARCHAR(50), price DECIMAL(10,2) NOT NULL)</code>；金额用 DECIMAL 不用 FLOAT；插入用一条多值 <code>INSERT INTO book (title, author, price) VALUES (...),(...)</code> 一次写完。</div></details>',
        '查询价格在 50~100 之间的书，按价格降序。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：返回的书价格都落在 50 到 100 之间（含边界），按价格从高到低排列，价格相同的两行先后顺序不保证。<b>为什么</b>：区间条件要用 BETWEEN 或大于等于加小于等于，写成 price 大于 50 且小于 100 会漏掉正好等于 50 和 100 的记录，这正是对账时少几条数据的典型原因。<b>要点</b>：<code>SELECT * FROM book WHERE price BETWEEN 50 AND 100 ORDER BY price DESC</code>；再用 EXPLAIN 确认过滤生效、没有多余的 Using filesort；数据量大时给 price 建索引。</div></details>',
        '统计每个作者的书数和平均价格，只显示书数 ≥ 2 的作者。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：结果每组一行，含作者、书数、均价三列，书数都大于等于 2，只写过一本书的作者不出现。<b>为什么</b>：书数是聚合后的值，过滤聚合结果必须用 HAVING，写进 WHERE 会因分组尚未发生而报错；AVG 自动忽略 NULL，分母只是非空价格的行数。<b>要点</b>：<code>SELECT author, COUNT(*) AS cnt, AVG(price) AS avg_price FROM book GROUP BY author HAVING COUNT(*) &gt;= 2</code>；均价用 <code>ROUND(AVG(price), 2)</code> 控制小数位；验证时把所有组的 cnt 相加应等于总行数。</div></details>',
        '用 JOIN 查询每本书的作者姓名，再用 UPDATE 修改一本价格并验证。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><b>预期现象</b>：JOIN 结果每行同时有书名和作者姓名，行数与 book 表一致；UPDATE 后重新查询只有一行价格变化，其他行不变。<b>为什么</b>：JOIN 漏写 ON 条件就退化成笛卡尔积，行数瞬间爆炸；UPDATE 忘了 WHERE 会改整张表，是最不可逆的操作之一。<b>要点</b>：<code>SELECT b.title, a.name FROM book b JOIN author a ON b.author_id = a.id</code>；更新前先用同样的条件 SELECT 一次确认命中行数，再 <code>UPDATE book SET price = 59.9 WHERE id = 3</code>。</div></details>'
      ] }
    ]
  };
})();
